contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // fund - amount to deposit into c
    function run(uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund)); require(fund <= 1000000000000000000000000000000);
        // ensure this test contract can send the requested fund to c
        require(address(this).balance >= fund);

        // read before-values
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeBalanceOfC = address(c).balance;

        // attempt Deposit and record whether it reverted
        bool reverted;
        c.Deposit{value: fund}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterBalanceOfC = address(c).balance;

        // General rule:
        // - If Deposit reverted then recorded balance unchanged and contract balance unchanged.
        // - If Deposit succeeded then recorded balance increased by exactly fund and contract balance increased by exactly fund.
        assert(
            (reverted && afterRecorded == beforeRecorded && afterBalanceOfC == beforeBalanceOfC)
            || (!reverted && afterRecorded == beforeRecorded + fund && afterBalanceOfC == beforeBalanceOfC + fund)
        );
    }

    receive() external payable {}
}

