pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 fund) internal {
        fund = bound(fund, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeBalanceOfC = address(c).balance;
        bool reverted;
        try c.Deposit{value: fund}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterBalanceOfC = address(c).balance;
        assertTrue((reverted && afterRecorded == beforeRecorded && afterBalanceOfC == beforeBalanceOfC)
            || (!reverted && afterRecorded == beforeRecorded + fund && afterBalanceOfC == beforeBalanceOfC + fund));
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
